H,W=17,30
g=[[0]*W for _ in range(H)]
# Relative color patterns from each object, all placed with top at row 7.
patterns={3:[[(0,c) for c in range(5)],[(1,2)],[(2,c) for c in range(1,4)],[(3,c) for c in range(5)],[(4,2)]],1:[[(0,c) for c in range(5)],[(1,2)],[(2,c) for c in range(1,4)],[(3,c) for c in range(5)],[(4,2)]],4:[[(0,c) for c in range(5)],[(1,2)],[(2,c) for c in range(1,4)],[(3,c) for c in range(5)],[(4,2)]],8:[[(0,c) for c in range(5)],[(1,2)],[(2,c) for c in range(1,4)],[(3,c) for c in range(5)],[(4,2)]]}
cols={3:2,1:9,4:14,8:21}
for color,rows in patterns.items():
    for dr,cells in enumerate(rows):
        for _,dc in cells:g[7+dr][cols[color]+dc]=color
print(len(g),set(map(len,g)))
print(repr(g))
